"""Source-backed UI state inventory for the Yubai Figma atlas (synthetic data)."""
import json
from pathlib import Path

flows = []
screens = []
def flow(key, title, summary, source):
    flows.append(dict(key=key,title=title,summary=summary,source=source,screens=[]))
def s(id,title,body,*,subtitle='',nav=None,back=None,save=None,caption='',variant='',status='实现映射 · 设计稿',footer=None):
    item=dict(id=id,title=title,body=body,subtitle=subtitle,nav=nav,back=back,save=save,caption=caption,variant=variant,status=status,footer=footer)
    screens.append(item);flows[-1]['screens'].append(id)
def text(t,style='Body'):return dict(type='text',text=t,style=style)
def note(t,b,mood='Info'):return dict(type='note',title=t,body=b,mood=mood)
def button(t,to,style='Primary'):return dict(type='button',label=t,to=to,style=style)
def field(label,value,to=None):return dict(type='field',label=label,value=value,to=to)
def row(label,value='›',to=None):return dict(type='row',label=label,value=value,to=to)
def toggle(label,on,to=None):return dict(type='toggle',label=label,on=on,to=to)
def entry(title,sub,amount,date='10月2日',to='L05'):return dict(type='entry',title=title,subtitle=sub,amount=amount,date=date,to=to)
def card(title,*items):return dict(type='card',title=title,items=items)
def tabs(items,selected=0):return dict(type='segments',items=[dict(label=a,to=b) for a,b in items],selected=selected)
def hero(amount='¥11,808.30',hidden=False,first=False):return dict(type='hero',amount=amount,hidden=hidden,first=first)
def chart(kind='funds'):return dict(type='chart',kind=kind)
def progress(label='正在本机读取与整理…',value=.42):return dict(type='progress',label=label,value=value)
def dialog(title,message,actions):return dict(type='dialog',title=title,message=message,actions=[dict(label=x,to=y,style=z) for x,y,z in actions])
def menu(title,items):return card(title,*[row(a,to=b) for a,b in items])
def money(label,value):return dict(type='money',label=label,value=value)

